public static Set FindOverridesForDataSourceBlock(TFMDataSourceBlock _block)
{
    Set overrides = new Set(Types::Class);
    ListEnumerator allOverrides = new SysDictClass(classNum(TFMDataSourceBlockValuesOverride)).extendedBy(true).getEnumerator();

    TFMDataSourceBlockValuesOverride override;
    while (allOverrides.moveNext())
    {
        override = new SysDictClass(allOverrides.current()).makeObject();
        if (override.hasModifications(_block) && override.getClassName() == classId2Name(classIdGet(_block)))
        {
            overrides.add(override);
        }
    }
    return overrides;
}
